def count_digit_one(n):
    total = 0
    for number in range(1, n + 1):
        temp = number
        while temp > 0:
            if temp % 10 == 1:
                total += 1              # this digit position holds a 1, count it
            temp //= 10                   # move to the next digit
    return total


if __name__ == "__main__":
    n = 13
    print(count_digit_one(n))

