def count_digit_one(n):
    total = 0
    base = 1                            # represents the place value: 1, 10, 100, ...
    while base <= n:
        high = n // (base * 10)           # the digits to the left of this position
        current = (n // base) % 10        # the digit currently sitting at this position
        low = n % base                    # the digits to the right of this position
        if current == 0:
            total += high * base
        elif current == 1:
            total += high * base + low + 1
        else:
            total += (high + 1) * base
        base *= 10                        # move to the next digit position
    return total


if __name__ == "__main__":
    n = 13
    print(count_digit_one(n))

